#!/usr/bin/env python3
"""
Trend Research and Content Intelligence Engine for @meowndr.

Discovers trending educational topics across YouTube Shorts, TikTok, and Instagram Reels,
calculates verified engagement and velocity metrics, applies 6-dimensional opportunity
scoring (0-100), filters out pseudoscience/disqualified topics, and transforms validated
trends into original Indonesian educational papercraft explainer reels.

Quality Improvements:
  - Independent Evidence Classification (VERIFIED_FACT, OBSERVED_TREND, MEASURED_METRICS,
    ESTIMATED_METRICS, INSUFFICIENT_EVIDENCE). Fact verification is strictly independent from
    trend popularity.
  - Evidence Confidence reported separately from 0-100 opportunity score.
  - Duplicate and saturation detection against existing episodes and historical research.
  - Production feasibility assessment (6-point check with custom asset flags).
  - Research repeatability with strict single-observation baseline rule.
"""

import os
import sys
import json
import math
import datetime
from typing import Dict, Any, List, Optional, Tuple

HERE = os.path.dirname(os.path.abspath(__file__))
REPO_ROOT = os.path.dirname(os.path.dirname(HERE))
sys.path.insert(0, HERE)

from schema_validator import validate_artifact

def get_iso_now() -> str:
    now = datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=7)))
    return now.isoformat(timespec="seconds")

def parse_iso_date(date_str: Optional[str]) -> Optional[datetime.datetime]:
    if not date_str:
        return None
    try:
        # Normalize trailing Z
        if date_str.endswith("Z"):
            date_str = date_str[:-1] + "+00:00"
        return datetime.datetime.fromisoformat(date_str)
    except Exception:
        return None


def load_env_if_present():
    """Loads key-value pairs from .env into os.environ if not already present."""
    candidates = [
        os.path.join(REPO_ROOT, ".env"),
        os.path.join(os.getcwd(), ".env")
    ]
    for ep in candidates:
        if os.path.exists(ep):
            try:
                with open(ep, "r", encoding="utf-8") as f:
                    for line in f:
                        line = line.strip()
                        if line and not line.startswith("#") and "=" in line:
                            k, v = line.split("=", 1)
                            k, v = k.strip(), v.strip()
                            if k not in os.environ and v:
                                os.environ[k] = v
            except Exception:
                pass


class MetricCalculator:
    """Calculates verifiable engagement and velocity indicators."""

    @staticmethod
    def calculate_engagement_rate(views: Optional[int], likes: Optional[int], comments: Optional[int], shares: Optional[int]) -> Optional[float]:
        if not views or views <= 0:
            return None
        l = likes if likes is not None else 0
        c = comments if comments is not None else 0
        s = shares if shares is not None else 0
        total_eng = l + c + s
        rate = (total_eng / float(views)) * 100.0
        return round(rate, 2)

    @staticmethod
    def calculate_view_velocity(views: Optional[int], pub_date_str: Optional[str], research_time_str: str) -> Optional[float]:
        if not views or views <= 0 or not pub_date_str:
            return None
        pub_dt = parse_iso_date(pub_date_str)
        res_dt = parse_iso_date(research_time_str)
        if not pub_dt or not res_dt:
            return None
        diff_hours = (res_dt - pub_dt).total_seconds() / 3600.0
        if diff_hours <= 0.05:  # under 3 minutes
            return None
        velocity = views / diff_hours
        return round(velocity, 1)


class EvidenceClassifier:
    """
    Independent evidence classification for @meowndr intelligence engine.

    Classifications:
      - VERIFIED_FACT: The underlying factual claim is supported by credible primary sources.
      - OBSERVED_TREND: Actual public platform observations support the trend.
      - MEASURED_METRICS: Metrics directly retrieved from an official/authorized API.
      - ESTIMATED_METRICS: Metrics are public estimates or curator observations.
      - INSUFFICIENT_EVIDENCE: Evidence is insufficient to support conclusion.

    STRICT INDEPENDENCE PRINCIPLES:
      - A factually verified topic is NOT automatically an observed trend.
      - A viral/trending topic is NOT automatically a verified fact.
    """

    CREDIBLE_SOURCE_KEYWORDS = [
        "journal", "study", "university", "usgs", "royal society",
        "nature", "plos", "annual review", "icdp", "mbari", "ieee",
        "science", "nasa", "noaa", "bmkg", "arxiv", "paper", "research",
        "peer-reviewed", "pubmed", "geological survey"
    ]

    @classmethod
    def is_fact_verified(cls, raw_trend: Dict[str, Any], factual_sources: Optional[List[Dict[str, Any]]] = None) -> bool:
        if factual_sources and len(factual_sources) > 0:
            for s in factual_sources:
                text = (s.get("source_name", "") + " " + s.get("url", "") + " " + s.get("claim", "")).lower()
                if any(kw in text for kw in cls.CREDIBLE_SOURCE_KEYWORDS):
                    return True
        evidence_notes = (raw_trend.get("evidence_notes") or "").lower()
        if any(kw in evidence_notes for kw in ["verified by", "journal", "studies", "archives", "usgs", "icdp", "bmkg", "nature", "plos"]):
            return True
        return False

    @classmethod
    def is_trend_observed(cls, raw_trend: Dict[str, Any]) -> bool:
        views = raw_trend.get("views")
        has_platform = bool(raw_trend.get("source_url") and raw_trend.get("platform"))
        if not has_platform:
            return False
        # Platform traction: views >= 10,000 or explicit trend evidence in notes
        if views is not None and views >= 10000:
            return True
        notes = (raw_trend.get("evidence_notes") or "").lower()
        if "trending" in notes or "viral" in notes or "surge" in notes:
            return True
        return False

    @classmethod
    def classify(cls, raw_trend: Dict[str, Any], factual_sources: Optional[List[Dict[str, Any]]] = None) -> List[str]:
        classifications = []

        fact_ok = cls.is_fact_verified(raw_trend, factual_sources)
        trend_ok = cls.is_trend_observed(raw_trend)

        if fact_ok:
            classifications.append("VERIFIED_FACT")
        if trend_ok:
            classifications.append("OBSERVED_TREND")

        # Metric measurement vs estimation
        if raw_trend.get("is_measured_metrics") is True:
            classifications.append("MEASURED_METRICS")
        elif raw_trend.get("views") is not None:
            classifications.append("ESTIMATED_METRICS")

        # Insufficient evidence if neither fact nor trend is confirmed, or quality is low
        if (not fact_ok and not trend_ok) or raw_trend.get("evidence_quality") == "low":
            classifications.append("INSUFFICIENT_EVIDENCE")

        return classifications

    @classmethod
    def calculate_evidence_confidence(
        cls,
        classifications: List[str],
        factual_sources: Optional[List[Dict[str, Any]]] = None,
        raw_trend: Optional[Dict[str, Any]] = None
    ) -> Dict[str, Any]:
        """
        Calculates separate evidence confidence (0-100).
        Reported strictly independent from the 0-100 opportunity score.
        """
        score = 50.0
        reasons = []

        if "VERIFIED_FACT" in classifications:
            score += 25.0
            reasons.append("Peer-reviewed primary research or authoritative scientific archives confirm factual claims.")
        else:
            score -= 20.0
            reasons.append("No authoritative primary scientific verification provided.")

        if "OBSERVED_TREND" in classifications:
            score += 15.0
            reasons.append("Confirmed multi-creator public engagement and platform velocity.")
        else:
            reasons.append("Lacks verified active viral platform traction.")

        if "MEASURED_METRICS" in classifications:
            score += 10.0
            reasons.append("Direct verified API metric measurement.")
        elif "ESTIMATED_METRICS" in classifications:
            reasons.append("Public fallback metric estimates with explicit non-measured disclosure.")

        if "INSUFFICIENT_EVIDENCE" in classifications:
            score -= 30.0
            reasons.append("Flagged for insufficient evidence.")

        final_score = max(0.0, min(100.0, round(score, 1)))

        if final_score >= 80.0:
            level = "HIGH"
        elif final_score >= 55.0:
            level = "MEDIUM"
        else:
            level = "LOW"

        return {
            "confidence_score": final_score,
            "confidence_level": level,
            "rationale": " ".join(reasons)
        }


class DuplicateDetector:
    """
    Detects potential duplicate and saturated topics across:
    1. Existing produced episodes in episodes/*
    2. Historical research runs in research/trends/*

    Rule: Never reject a topic solely because it has appeared before.
    Identifies whether a new angle provides distinct educational value.
    """

    def __init__(self, episodes_dir: Optional[str] = None, research_dir: Optional[str] = None):
        self.episodes_dir = episodes_dir or os.path.join(REPO_ROOT, "episodes")
        self.research_dir = research_dir or os.path.join(REPO_ROOT, "research", "trends")
        self.existing_episodes = self._load_existing_episodes()
        self.historical_topics = self._load_historical_topics()

    def _load_existing_episodes(self) -> List[Dict[str, Any]]:
        episodes = []
        if not os.path.isdir(self.episodes_dir):
            return episodes
        for ep_name in os.listdir(self.episodes_dir):
            ep_path = os.path.join(self.episodes_dir, ep_name)
            if not os.path.isdir(ep_path):
                continue
            title = ep_name
            slug_words = ep_name.replace("-", " ").replace("_", " ")
            desc_parts = [slug_words]

            # Check episode.json in root or papercut/
            for cand_json in [os.path.join(ep_path, "episode.json"), os.path.join(ep_path, "papercut", "episode.json")]:
                if os.path.isfile(cand_json):
                    try:
                        with open(cand_json, "r", encoding="utf-8") as f:
                            data = json.load(f)
                            meta = data.get("meta", {})
                            if data.get("title") or meta.get("title"):
                                title = data.get("title") or meta.get("title")
                            for field_val in [
                                data.get("topic"),
                                data.get("description"),
                                meta.get("topic"),
                                meta.get("title"),
                            ]:
                                if field_val:
                                    desc_parts.append(str(field_val))
                    except Exception:
                        pass

            # Check narration script or research facts for semantic context
            sc_path = os.path.join(ep_path, "narration", "script.json")
            if os.path.isfile(sc_path):
                try:
                    with open(sc_path, "r", encoding="utf-8") as f:
                        sc = json.load(f)
                        if isinstance(sc, list):
                            desc_parts.extend([line.get("text", "") for line in sc[:3]])
                except Exception:
                    pass

            facts_path = os.path.join(ep_path, "research", "facts.md")
            if os.path.isfile(facts_path):
                try:
                    with open(facts_path, "r", encoding="utf-8") as f:
                        desc_parts.append(f.read()[:500])
                except Exception:
                    pass

            episodes.append({
                "slug": ep_name,
                "title": title,
                "description": " ".join(desc_parts)
            })
        return episodes

    def _load_historical_topics(self) -> List[Dict[str, Any]]:
        topics = []
        if not os.path.isdir(self.research_dir):
            return topics
        for d in os.listdir(self.research_dir):
            d_path = os.path.join(self.research_dir, d)
            if not os.path.isdir(d_path):
                continue
            data_file = os.path.join(d_path, "trend-data.json")
            if os.path.isfile(data_file):
                try:
                    with open(data_file, "r", encoding="utf-8") as f:
                        data = json.load(f)
                        for opp in data.get("evaluated_opportunities", []):
                            topics.append({
                                "date": d,
                                "id": opp.get("id"),
                                "title": opp.get("proposed_title", ""),
                                "niche": opp.get("niche", "")
                            })
                except Exception:
                    pass
        return topics

    def assess_topic(
        self,
        topic_title: str,
        concept: Dict[str, Any],
        raw_trend_id: str,
        target_date: Optional[str] = None
    ) -> Tuple[Dict[str, Any], Dict[str, Any]]:
        """
        Returns (existing_episode_originality, duplicate_assessment).
        """
        norm_title = topic_title.lower()
        stopwords = {
            "yang", "dan", "di", "ke", "dari", "ini", "itu", "untuk", "pada", "adalah",
            "the", "in", "of", "and", "to", "kenapa", "mengapa", "bagaimana", "rahasia",
            "manusia", "bisa", "saat", "kita", "kamu", "pernah", "nggak", "selalu",
            "sudah", "akan", "lebih", "tapi", "jika", "bukan", "hanya", "dengan", "dalam",
            "banyak", "orang", "tahu", "tahukah", "rasanya"
        }
        
        # Include semantic concepts from question and keywords
        concept_semantic = (
            topic_title + " " +
            concept.get("main_question", "") + " " +
            " ".join(concept.get("relevant_keywords", []))
        ).lower().replace("-", " ").replace("_", " ")
        words = set([w.strip("?,.:;\"'()") for w in concept_semantic.split() if len(w) > 3 and w not in stopwords])

        matched_ep = None
        max_overlap = 0
        for ep in self.existing_episodes:
            ep_text = (ep["slug"].replace("-", " ") + " " + ep["title"] + " " + ep["description"]).lower().replace("-", " ").replace("_", " ")
            ep_words = set([w.strip("?,.:;\"'()") for w in ep_text.split() if len(w) > 3 and w not in stopwords])
            overlap = len(words.intersection(ep_words))
            if overlap > max_overlap:
                max_overlap = overlap
                matched_ep = ep["slug"]

        # Check historical research runs (excluding target_date)
        matched_prior_research = None
        for hist in self.historical_topics:
            if target_date and hist.get("date") == target_date:
                continue
            hist_title = hist.get("title", "").lower().replace("-", " ")
            hist_words = set([w.strip("?,.:;\"'()") for w in hist_title.split() if len(w) > 3 and w not in stopwords])
            if len(words.intersection(hist_words)) >= 3 or raw_trend_id in str(hist.get("id")):
                matched_prior_research = f"{hist['date']} / {hist['id']}"
                break

        if max_overlap >= 4:
            similarity = "HIGH"
            comp_status = "POTENTIAL_OVERLAP"
            is_dup = True
        elif max_overlap >= 2:
            similarity = "MODERATE"
            comp_status = "NEW_ANGLE_ON_FAMILIAR_THEME"
            is_dup = False
        elif max_overlap == 1:
            similarity = "LOW"
            comp_status = "NEW_ANGLE_ON_FAMILIAR_THEME"
            is_dup = False
        else:
            similarity = "NONE"
            comp_status = "DISTINCT_NEW_TOPIC"
            is_dup = False
            is_dup = False

        new_angle = self._generate_new_angle_justification(norm_title, matched_ep, comp_status)

        episode_originality = {
            "comparison_status": comp_status,
            "similar_episodes": [matched_ep] if matched_ep and max_overlap >= 1 else [],
            "originality_notes": f"Compared with {len(self.existing_episodes)} existing episodes in library. Status: {comp_status}."
        }

        duplicate_assessment = {
            "is_duplicate": is_dup,
            "similarity_level": similarity,
            "matched_existing_episode": matched_ep if max_overlap >= 1 else None,
            "matched_previous_research": matched_prior_research,
            "new_angle_justification": new_angle
        }

        return episode_originality, duplicate_assessment

