class TrendValidator:
    """Verifies all prompt validation constraints and quality rules on generated artifacts."""

    @staticmethod
    def validate(data: Dict[str, Any]) -> Tuple[bool, List[str]]:
        errors = []

        # 1. JSON Schema validation
        valid, schema_errs = validate_artifact("trend_intelligence", data)
        if not valid:
            for se in schema_errs:
                errors.append(f"Schema Error: {se}")

        # 2. Every trend has a source and valid URL
        for t in data.get("raw_trends", []):
            if not t.get("source_url") or not t["source_url"].startswith("http"):
                errors.append(f"Trend '{t.get('id')}' is missing a valid HTTP/HTTPS source URL.")
            if not t.get("creator_or_channel"):
                errors.append(f"Trend '{t.get('id')}' is missing creator/channel information.")

        # 3. Every metric has a retrieval timestamp
        for t in data.get("raw_trends", []):
            if not t.get("research_timestamp"):
                errors.append(f"Trend '{t.get('id')}' is missing research_timestamp.")

        # 4. Calculations use valid inputs (no negative numbers, no division by zero)
        for t in data.get("raw_trends", []):
            views = t.get("views")
            eng = t.get("engagement_rate")
            vel = t.get("view_velocity")
            if views is not None and views < 0:
                errors.append(f"Trend '{t.get('id')}' has negative view count.")
            if eng is not None and (eng < 0 or eng > 100):
                errors.append(f"Trend '{t.get('id')}' has invalid engagement rate: {eng}%.")
            if vel is not None and vel < 0:
                errors.append(f"Trend '{t.get('id')}' has negative view velocity: {vel}.")

        # 5. Trend scores are strictly between 0 and 100 and have explainable reasoning
        for opp in data.get("evaluated_opportunities", []):
            sc = opp.get("scoring", {})
            tot = sc.get("total_score", -1)
            if tot < 0 or tot > 100:
                errors.append(f"Opportunity '{opp.get('id')}' total score out of bounds: {tot}.")
            expected_sum = round(
                sc.get("trend_momentum", 0) +
                sc.get("relevance_to_meowndr", 0) +
                sc.get("educational_value", 0) +
                sc.get("visual_storytelling_potential", 0) +
                sc.get("originality_differentiation", 0) +
                sc.get("evergreen_value", 0), 1
            )
            if abs(expected_sum - tot) > 0.5:
                errors.append(f"Opportunity '{opp.get('id')}' total score mismatch: sum={expected_sum}, reported={tot}.")
            if not sc.get("reasoning") or len(sc["reasoning"]) < 20:
                errors.append(f"Opportunity '{opp.get('id')}' lacks adequate written scoring reasoning.")

            # Evidence confidence validation
            conf = opp.get("evidence_confidence", {})
            c_score = conf.get("confidence_score")
            if c_score is None or c_score < 0 or c_score > 100:
                errors.append(f"Opportunity '{opp.get('id')}' invalid evidence confidence score: {c_score}.")

            # Research repeatability rule: never infer trend growth from single observation
            rep = opp.get("research_repeatability", {})
            obs_cnt = rep.get("observation_count", 1)
            growth_cls = rep.get("trend_growth_classification")
            if obs_cnt == 1 and growth_cls != "SINGLE_OBSERVATION_BASELINE":
                errors.append(
                    f"Opportunity '{opp.get('id')}' violated repeatability rule: observation_count is 1 but growth was classified as '{growth_cls}' instead of 'SINGLE_OBSERVATION_BASELINE'."
                )

        # 6. Rejection reasons exist for disqualified topics
        for rej in data.get("rejected_topics", []):
            if not rej.get("rejection_reason"):
                errors.append(f"Rejected topic '{rej.get('topic')}' missing rejection reason.")
            if not rej.get("disqualification_category"):
                errors.append(f"Rejected topic '{rej.get('topic')}' missing disqualification category.")

        # 7. Disclosures exist
        disc = data.get("limitations_and_disclosures", {})
        if not disc.get("youtube_api_status") or not disc.get("tiktok_api_status") or not disc.get("instagram_api_status"):
            errors.append("Limitations and disclosures are incomplete.")

        return len(errors) == 0, errors


def run_trend_research_pipeline(date_str: Optional[str] = None, niche: Optional[str] = None, force: bool = True) -> Dict[str, Any]:
    """Orchestrates end-to-end trend discovery, scoring, validation, and file generation."""
    target_date = date_str or datetime.date.today().isoformat()
    now_iso = get_iso_now()

    harvester = TrendHarvester()
    statuses = harvester.get_platform_statuses()
    raw_trends, rejected_topics = harvester.harvest(niche=niche)

    history_tracker = ResearchRepeatabilityTracker()
    duplicate_detector = DuplicateDetector()

    evaluated_opportunities = []
    for t in raw_trends:
        opp = OpportunityScorer.score_topic(
            t,
            history_tracker=history_tracker,
            duplicate_detector=duplicate_detector,
            target_date=target_date
        )
        evaluated_opportunities.append(opp)

    # Sort ORIGINAL What-If opportunities first, then by total_score descending
    evaluated_opportunities.sort(
        key=lambda o: (
            0 if o.get("duplicate_assessment", {}).get("originality_status") == "ORIGINAL" else 1,
            -float(o.get("scoring", {}).get("total_score", 0.0)),
        )
    )

    intelligence_payload = {
        "generated_at": now_iso,
        "research_date": target_date,
        "target_audience": "Remaja & dewasa muda Indonesia (15–35 tahun), penikmat edukasi sains, sejarah, dan misteri berbasis visual papercraft",
        "niches_covered": list(set([t.get("niche", "general") for t in raw_trends])),
        "platforms_monitored": statuses,
        "raw_trends": raw_trends,
        "evaluated_opportunities": evaluated_opportunities,
        "rejected_topics": rejected_topics,
        "limitations_and_disclosures": {
            "youtube_api_status": "YOUTUBE_API_KEY unconfigured; operating in public trend discovery fallback mode. API quota cost: 1 unit for mostPopular, 100 units for search.",
            "tiktok_api_status": "TikTok Research API is legally restricted to academic institutions. TikTok Commercial API unconfigured. Operating via TikTok Creative Center public trend indicators & Indonesian hashtag surveillance.",
            "instagram_api_status": "Meta Graph API does not support public global Reels exploration or public hashtag search. Operating via public edutainment explore patterns and verified curator monitoring.",
            "disclaimer": "All research complies strictly with platform Terms of Service, robots.txt, and privacy boundaries. No private APIs were reverse-engineered and zero CAPTCHAs were bypassed. The creator maintains final approval sovereignty over topic selection."
        }
    }

    # Validate payload
    valid, errors = TrendValidator.validate(intelligence_payload)
    if not valid:
        raise ValueError(f"Trend intelligence validation failed:\n" + "\n".join(errors))

    # Export deliverables
    exporter = ArtifactExporter(output_date=target_date)
    file_map = exporter.export_all(intelligence_payload, force=force)

    return {
        "status": "SUCCESS",
        "date": target_date,
        "payload": intelligence_payload,
        "files": file_map,
        "validation_passed": True
    }


if __name__ == "__main__":
    res = run_trend_research_pipeline()
    print(f"[OK] Trend research successfully executed for {res['date']}:")
    for k, v in res["files"].items():
        print(f"  - {k}: {v}")
